# Generated by scripts/build-windows-bootstrap.mjs
function Assert-DiskWatchPath([string]$Path) {
  if (-not [IO.Path]::IsPathRooted($Path) -or $Path.Contains('"') -or $Path.Contains("`n") -or $Path.Contains("`r")) { throw 'Unsafe install path.' }
  $current = [IO.Path]::GetFullPath($Path)
  while ($current) {
    if (Test-Path -LiteralPath $current) {
      $item = Get-Item -LiteralPath $current -Force
      if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or -not $item.PSIsContainer) { throw "Linked or non-directory install path: $current" }
    }
    $current = Split-Path -Path $current -Parent
  }
}

function Install-DiskWatch {
  param([string]$Installer, [string]$ExpectedHash, [string]$InstallDirectory, [int]$ParentProcessId, [string]$ProfileDirectory, [switch]$Restart)
  if (-not [Environment]::Is64BitOperatingSystem -or $env:PROCESSOR_ARCHITECTURE -ne 'AMD64') { throw 'Disk Watch requires Windows x64 and 64-bit PowerShell.' }
  if ($ExpectedHash -notmatch '^[0-9a-fA-F]{64}$') { throw 'Invalid installer checksum.' }
  if ((Get-FileHash -LiteralPath $Installer -Algorithm SHA256).Hash -ne $ExpectedHash) { throw 'SHA256 verification failed. The installed app was not changed.' }
  Assert-DiskWatchPath $InstallDirectory
  $InstallDirectory = [IO.Path]::GetFullPath($InstallDirectory).TrimEnd('\')
  if ((Split-Path $InstallDirectory -Leaf) -ne 'Disk Watch') { throw 'The install directory must end in Disk Watch.' }
  $parent = Split-Path $InstallDirectory -Parent
  [IO.Directory]::CreateDirectory($parent) | Out-Null
  $lock = Join-Path $parent '.disk-watch-install.lock'
  if ((Test-Path -LiteralPath $lock) -and ((Get-Item -LiteralPath $lock -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Unsafe installer lock.' }
  $lockStream = [IO.File]::Open($lock, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, [IO.FileShare]::None)
  $backup = Join-Path $parent ('.disk-watch-previous-' + [Guid]::NewGuid().ToString('N'))
  $hadPrevious = $false
  $changed = $false
  try {
    if ($ParentProcessId -gt 0) {
      $process = Get-Process -Id $ParentProcessId -ErrorAction SilentlyContinue
      if ($process -and -not $process.WaitForExit(120000)) { throw 'Disk Watch did not exit within two minutes.' }
    }
    $executable = Join-Path $InstallDirectory 'Disk Watch.exe'
    $running = Get-CimInstance Win32_Process -Filter "Name = 'Disk Watch.exe'" | Where-Object {
      $_.ExecutablePath -and [StringComparer]::OrdinalIgnoreCase.Equals($_.ExecutablePath, $executable)
    }
    if ($running) { throw 'Quit the installed Disk Watch before installing.' }
    if (Test-Path -LiteralPath $InstallDirectory) {
      if (-not (Test-Path -LiteralPath $executable -PathType Leaf) -or -not (Test-Path -LiteralPath (Join-Path $InstallDirectory 'resources\app.asar') -PathType Leaf)) { throw 'Refusing to replace an unrelated directory.' }
      # Copy the entire old app before NSIS changes files. User data is outside this directory.
      Copy-Item -LiteralPath $InstallDirectory -Destination $backup -Recurse
      $hadPrevious = $true
    }
    $changed = $true
    $process = Start-Process -FilePath $Installer -ArgumentList @('/S', '/currentuser', "/D=$InstallDirectory") -Wait -PassThru -WindowStyle Hidden
    if ($process.ExitCode -ne 0) { throw "Installer failed with exit code $($process.ExitCode)." }
    if (-not (Test-Path -LiteralPath $executable -PathType Leaf) -or -not (Test-Path -LiteralPath (Join-Path $InstallDirectory 'resources\dw-scan.exe') -PathType Leaf)) { throw 'Installed app verification failed.' }
    Set-Content -LiteralPath (Join-Path $InstallDirectory '.disk-watch-managed') -Value 'com.irudd.diskwatch' -Encoding ASCII
    if ($Restart) {
      $arguments = @()
      if ($ProfileDirectory) {
        if ($ProfileDirectory.Contains('"') -or $ProfileDirectory.Contains("`n") -or $ProfileDirectory.Contains("`r")) { throw 'Invalid profile path.' }
        $quotedProfile = $ProfileDirectory -replace '(\\+)$', '$1$1'
        $arguments = @('"--user-data-dir=' + $quotedProfile + '"')
      }
      if ($arguments.Count) { Start-Process -FilePath $executable -ArgumentList $arguments | Out-Null }
      else { Start-Process -FilePath $executable | Out-Null }
    }
    $changed = $false
    if ($hadPrevious) { Remove-Item -LiteralPath $backup -Recurse -Force }
    Write-Output "Installed: $executable"
  } catch {
    $failure = $_
    if ($changed) {
      if (Test-Path -LiteralPath $InstallDirectory) { Remove-Item -LiteralPath $InstallDirectory -Recurse -Force }
      if ($hadPrevious) { Move-Item -LiteralPath $backup -Destination $InstallDirectory }
    }
    throw $failure
  } finally {
    $lockStream.Dispose()
    # Leave the lock file in place. Deleting it after unlocking allows two separate lock files.
  }
}

$ErrorActionPreference = 'Stop'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
if (-not [Environment]::Is64BitOperatingSystem -or $env:PROCESSOR_ARCHITECTURE -ne 'AMD64') { throw 'Disk Watch requires Windows x64 and 64-bit PowerShell.' }
$repo = 'alundgren/irudd-disk-watch'
$stage = Join-Path ([IO.Path]::GetTempPath()) ('disk-watch-install-' + [Guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($stage) | Out-Null
function Save-DiskWatchDownload([string]$Url, [string]$File, [long]$Limit) {
  Add-Type -AssemblyName System.Net.Http
  $client = New-Object Net.Http.HttpClient
  $client.DefaultRequestHeaders.UserAgent.ParseAdd('Disk-Watch/0.2.0')
  if (([Uri]$Url).Host -eq 'api.github.com' -and -not ([Uri]$Url).AbsolutePath.Contains('/releases/assets/')) { $client.DefaultRequestHeaders.Accept.ParseAdd('application/vnd.github+json') }
  else { $client.DefaultRequestHeaders.Accept.ParseAdd('application/octet-stream') }
  if ($env:DISK_WATCH_GITHUB_TOKEN -and ([Uri]$Url).Host -eq 'api.github.com') { $client.DefaultRequestHeaders.Authorization = New-Object Net.Http.Headers.AuthenticationHeaderValue('Bearer', $env:DISK_WATCH_GITHUB_TOKEN) }
  $cancel = New-Object Threading.CancellationTokenSource
  $cancel.CancelAfter(180000)
  $response = $null; $inputStream = $null; $outputStream = $null
  try {
    $response = $client.GetAsync($Url, [Net.Http.HttpCompletionOption]::ResponseHeadersRead, $cancel.Token).GetAwaiter().GetResult()
    $response.EnsureSuccessStatusCode() | Out-Null
    $uri = $response.RequestMessage.RequestUri
    if ($uri.Scheme -ne 'https' -or $uri.Host -notin @('api.github.com', 'github.com', 'release-assets.githubusercontent.com', 'objects.githubusercontent.com')) { throw 'Release download redirected outside GitHub.' }
    if ($response.Content.Headers.ContentLength -gt $Limit) { throw 'Download exceeds size limit.' }
    $inputStream = $response.Content.ReadAsStreamAsync().GetAwaiter().GetResult()
    $outputStream = [IO.File]::Open($File, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
    $buffer = New-Object byte[] 65536
    [long]$total = 0
    while (($count = $inputStream.ReadAsync($buffer, 0, $buffer.Length, $cancel.Token).GetAwaiter().GetResult()) -gt 0) {
      $total += $count
      if ($total -gt $Limit) { throw 'Download exceeds size limit.' }
      $outputStream.Write($buffer, 0, $count)
    }
  } finally {
    if ($outputStream) { $outputStream.Dispose() }; if ($inputStream) { $inputStream.Dispose() }
    if ($response) { $response.Dispose() }; $client.Dispose(); $cancel.Dispose()
  }
}
try {
$metadata = Join-Path $stage 'release.json'
Save-DiskWatchDownload "https://api.github.com/repos/$repo/releases/latest" $metadata 1048576
$release = Get-Content -LiteralPath $metadata -Raw | ConvertFrom-Json
if ($release.draft -or $release.prerelease -or $release.tag_name -notmatch '^v(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$') { throw 'Invalid stable release.' }
$version = $release.tag_name.Substring(1)
$asset = "Disk-Watch-$version-x64-Setup.exe"
$expectedNames = @('Disk-Watch-mac-arm64.tar.gz', $asset, 'dw-scan-linux-x64', 'dw-scan-linux-arm64', 'SHA256SUMS')
if ($release.assets.Count -ne 5) { throw 'Incomplete release.' }
$assetIds = @{}
foreach ($name in $expectedNames) {
  $matching = @($release.assets | Where-Object { $_.name -ceq $name -and $_.state -eq 'uploaded' -and $_.browser_download_url -ceq "https://github.com/$repo/releases/download/v$version/$name" })
  if ($matching.Count -ne 1 -or [string]$matching[0].id -notmatch '^[1-9][0-9]*$') { throw 'Invalid release assets.' }
  $assetIds[$name] = $matching[0].id
}
  $base = "https://github.com/$repo/releases/download/v$version"
  $manifestPath = Join-Path $stage 'SHA256SUMS'
  $manifestUrl = "$base/SHA256SUMS"
  $installerUrl = "$base/$asset"
  if ($env:DISK_WATCH_GITHUB_TOKEN) {
    $manifestUrl = "https://api.github.com/repos/$repo/releases/assets/$($assetIds['SHA256SUMS'])"
    $installerUrl = "https://api.github.com/repos/$repo/releases/assets/$($assetIds[$asset])"
  }
  Save-DiskWatchDownload $manifestUrl $manifestPath 1048576
  $manifest = Get-Content -LiteralPath $manifestPath -Raw
  $checksums = @{}
  foreach ($line in ($manifest.Trim() -split "`n")) {
    if ($line.TrimEnd("`r") -notmatch '^([a-fA-F0-9]{64}) [ *]([^/\\\r\n]+)$') { throw 'Invalid checksum manifest.' }
    $name = $Matches[2]
    if ($name -cnotin $expectedNames -or $name -eq 'SHA256SUMS' -or $checksums.ContainsKey($name)) { throw 'Invalid checksum asset.' }
    $checksums[$name] = $Matches[1]
  }
  if ($checksums.Count -ne 4) { throw 'Incomplete checksum manifest.' }
  $installer = Join-Path $stage $asset
  Save-DiskWatchDownload $installerUrl $installer 734003200
  Install-DiskWatch -Installer $installer -ExpectedHash $checksums[$asset] -InstallDirectory (Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'Programs\Disk Watch')
  Write-Output 'Search Start for Disk Watch. The installer does not launch the app. History and settings are preserved.'
} finally { Remove-Item -LiteralPath $stage -Recurse -Force }
